import fs from 'fs-extra';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Component data cache
let componentData = null;
let categoriesData = null;

// React Bits repository URL for fetching data
const REACT_BITS_REPO = 'https://api.github.com/repos/davidhdev/react-bits';
const REACT_BITS_RAW = 'https://raw.githubusercontent.com/davidhdev/react-bits/main';

/**
 * Initialize component data from React Bits repository
 */
export async function initializeData() {
  try {
    // Load component mappings
    await loadComponentMappings();
    
    // Load categories
    await loadCategories();
    
    console.error('Component data initialized successfully');
  } catch (error) {
    console.error('Failed to initialize component data:', error.message);
    // Use fallback data if available
    loadFallbackData();
  }
}

/**
 * Load component mappings from the repository
 */
async function loadComponentMappings() {
  try {
    const response = await fetch(`${REACT_BITS_RAW}/src/constants/Components.js`);
    const content = await response.text();
    
    // Parse the JavaScript file to extract component mappings
    componentData = parseComponentMappings(content);
  } catch (error) {
    console.error('Failed to load component mappings:', error.message);
    throw error;
  }
}

/**
 * Load categories from the repository
 */
async function loadCategories() {
  try {
    const response = await fetch(`${REACT_BITS_RAW}/src/constants/Categories.js`);
    const content = await response.text();
    
    // Parse categories
    categoriesData = parseCategoriesData(content);
  } catch (error) {
    console.error('Failed to load categories:', error.message);
    // Use default categories
    categoriesData = getDefaultCategories();
  }
}

/**
 * Parse component mappings from Components.js content
 */
function parseComponentMappings(content) {
  const components = {
    animations: {},
    textAnimations: {},
    components: {},
    backgrounds: {}
  };

  try {
    // Extract animations
    const animationsMatch = content.match(/const animations = \{([\s\S]*?)\};/);
    if (animationsMatch) {
      components.animations = parseComponentObject(animationsMatch[1]);
    }

    // Extract text animations
    const textAnimationsMatch = content.match(/const textAnimations = \{([\s\S]*?)\};/);
    if (textAnimationsMatch) {
      components.textAnimations = parseComponentObject(textAnimationsMatch[1]);
    }

    // Extract components
    const componentsMatch = content.match(/const components = \{([\s\S]*?)\};/);
    if (componentsMatch) {
      components.components = parseComponentObject(componentsMatch[1]);
    }

    // Extract backgrounds
    const backgroundsMatch = content.match(/const backgrounds = \{([\s\S]*?)\};/);
    if (backgroundsMatch) {
      components.backgrounds = parseComponentObject(backgroundsMatch[1]);
    }

    return components;
  } catch (error) {
    console.error('Error parsing component mappings:', error.message);
    return getDefaultComponents();
  }
}

/**
 * Parse individual component object from string
 */
function parseComponentObject(objectString) {
  const components = {};
  
  // Match component entries like: 'component-name': () => import("../demo/path")
  const componentRegex = /'([^']+)':\s*\(\)\s*=>\s*import\("([^"]+)"\)/g;
  let match;
  
  while ((match = componentRegex.exec(objectString)) !== null) {
    const [, name, importPath] = match;
    components[name] = {
      name,
      importPath,
      category: getCategoryFromPath(importPath),
      description: generateDescription(name)
    };
  }
  
  return components;
}

/**
 * Get category from import path
 */
function getCategoryFromPath(importPath) {
  if (importPath.includes('/Animations/')) return 'animations';
  if (importPath.includes('/TextAnimations/')) return 'text-animations';
  if (importPath.includes('/Components/')) return 'components';
  if (importPath.includes('/Backgrounds/')) return 'backgrounds';
  return 'components';
}

