    'chroma-grid': 'Chromatic grid background effect',
    'profile-card': 'Animated profile card component',
    'card-swap': 'Card swapping animation component',
    'model-viewer': '3D model viewer component',
    'fluid-glass': 'Fluid glass morphism effect',
    'masonry': 'Masonry layout component',
    'magic-bento': 'Magic bento grid layout',
    'orb': 'Animated orb background effect',
    'particles': 'Particle system background',
    'liquid-chrome': 'Liquid chrome background effect',
