/**
 * Parse categories data
 */
function parseCategoriesData(content) {
  // Default categories structure
  return getDefaultCategories();
}

/**
 * Get default categories
 */
function getDefaultCategories() {
  return {
    animations: {
      name: 'Animations',
      description: 'General animation components',
      count: 0
    },
    'text-animations': {
      name: 'Text Animations',
      description: 'Text-specific animation effects',
      count: 0
    },
    components: {
      name: 'Components',
      description: 'Interactive UI components',
      count: 0
    },
    backgrounds: {
      name: 'Backgrounds',
      description: 'Background animation effects',
      count: 0
    }
  };
}

/**
 * Get default components (fallback)
 */
function getDefaultComponents() {
  return {
    animations: {},
    textAnimations: {},
    components: {
      'stack': {
        name: 'stack',
        category: 'components',
        description: 'A stacked card component with smooth animations'
      },
      'dock': {
        name: 'dock',
        category: 'components',
        description: 'macOS-style dock component with hover effects'
      }
    },
    backgrounds: {}
  };
}

/**
 * Load fallback data when remote loading fails
 */
function loadFallbackData() {
  componentData = getDefaultComponents();
  categoriesData = getDefaultCategories();
  console.error('Using fallback component data');
}

/**
 * Get all component data
 */
export function getComponentData() {
  return componentData;
}

/**
 * Get categories data
 */
export function getCategoriesData() {
  return categoriesData;
}

/**
 * Get component by name
 */
export function getComponentByName(name) {
  if (!componentData) return null;
  
  for (const category of Object.values(componentData)) {
    if (category[name]) {
      return category[name];
    }
  }
  
  return null;
}

/**
 * Search components by query
 */
export function searchComponentsByQuery(query, category = null, limit = 10) {
  if (!componentData) return [];
  
  const results = [];
  const searchTerm = query.toLowerCase();
  
  for (const [categoryName, components] of Object.entries(componentData)) {
    if (category && categoryName !== category) continue;
    
    for (const component of Object.values(components)) {
      if (
        component.name.toLowerCase().includes(searchTerm) ||
        component.description.toLowerCase().includes(searchTerm)
      ) {
        results.push({
          ...component,
          category: categoryName
        });
      }
    }
  }
  
  return results.slice(0, limit);
}
